using DareuLocal.Core;
using DareuLocal.App;
DeviceIdentityProbe.ResolveReceivers();var endpoint=Hardware.PreferredEndpoints(Hardware.Endpoints()).First(x=>x.CanConfigure&&x.Kind==DeviceKind.Keyboard&&x.Product?.HasMatrix==true);LightingState original;using(var device=new TgKeyboard(endpoint)){device.ReadState();original=device.ReadLight(1);}Console.WriteLine("Starting audio loopback lighting smoke test for "+endpoint.Name);var session=await AudioLightingSession.Start(endpoint,1,new byte[]{255,100,40},8,0.3);double peak=0;try{for(int i=0;i<15;i++){await Task.Delay(100);peak=Math.Max(peak,session.Level);}}finally{await session.Stop();}if(session.Error!=null)throw new IOException(session.Error);using(var device=new TgKeyboard(endpoint)){device.ReadState();var restored=device.ReadLight(1);if(restored.Effect!=original.Effect||restored.Brightness!=original.Brightness)throw new IOException("Original lighting not restored");}Console.WriteLine($"PASS WASAPI capture start / stop, RGB frames and lighting restore; observed normalized level {peak:F3}");
